CREATE TABLE public.org_autoridad_calidad (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid NOT NULL REFERENCES public.organizations(id), version integer NOT NULL, modo text NOT NULL CHECK (modo IN ('con_ac','designado','rs_maxima')), autorizadores uuid[] NOT NULL DEFAULT '{}', motivo text NOT NULL, created_by uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(org_id,version));
GRANT SELECT ON public.org_autoridad_calidad TO authenticated; GRANT ALL ON public.org_autoridad_calidad TO service_role;
ALTER TABLE public.org_autoridad_calidad ENABLE ROW LEVEL SECURITY;
CREATE POLICY leer ON public.org_autoridad_calidad FOR SELECT TO authenticated USING (org_id=(SELECT public.get_user_org_id()));
CREATE OR REPLACE FUNCTION public.mi_autoridad_calidad() RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE org uuid:=public.get_user_org_id(); c public.org_autoridad_calidad; modo text; ids uuid[]; BEGIN IF org IS NULL OR auth.uid() IS NULL THEN RAISE EXCEPTION 'Sin empresa activa'; END IF; SELECT * INTO c FROM public.org_autoridad_calidad WHERE org_id=org ORDER BY version DESC LIMIT 1; IF FOUND THEN RETURN to_jsonb(c); END IF; modo:=CASE WHEN EXISTS(SELECT 1 FROM public.org_members m JOIN public.profiles p ON p.id=m.user_id AND p.activo WHERE m.org_id=org AND m.role='aseguramiento_calidad') THEN 'con_ac' ELSE 'designado' END; SELECT autorizadores INTO ids FROM public.kpi_reporte_config WHERE org_id=org ORDER BY version DESC LIMIT 1; RETURN jsonb_build_object('org_id',org,'version',0,'modo',modo,'autorizadores',coalesce(ids,'{}')); END $$;
REVOKE ALL ON FUNCTION public.mi_autoridad_calidad() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.mi_autoridad_calidad() TO authenticated;
CREATE OR REPLACE FUNCTION public.guardar_autoridad_calidad(_modo text,_autorizadores uuid[],_motivo text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE org uuid:=public.get_user_org_id(); nid uuid; ver integer; BEGIN IF org IS NULL OR public.is_super_admin() OR NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Solo el administrador cambia la autoridad de calidad'; END IF; IF length(btrim(coalesce(_motivo,'')))<5 THEN RAISE EXCEPTION 'Motivo obligatorio (mínimo 5 caracteres)'; END IF; IF _modo NOT IN ('con_ac','designado','rs_maxima') THEN RAISE EXCEPTION 'Modelo de autoridad no válido'; END IF; IF EXISTS(SELECT 1 FROM unnest(coalesce(_autorizadores,'{}')) u WHERE NOT EXISTS(SELECT 1 FROM public.org_members m JOIN public.profiles p ON p.id=m.user_id AND p.activo WHERE m.org_id=org AND m.user_id=u AND m.role<>'super_admin')) THEN RAISE EXCEPTION 'Selecciona personas activas de la empresa'; END IF; PERFORM pg_advisory_xact_lock(hashtextextended(org::text,819)); SELECT coalesce(max(version),0)+1 INTO ver FROM public.org_autoridad_calidad WHERE org_id=org; PERFORM set_config('tracea.autoridad_rpc','1',true); PERFORM set_config('tracea.motivo',btrim(_motivo),true); INSERT INTO public.org_autoridad_calidad(org_id,version,modo,autorizadores,motivo,created_by) VALUES(org,ver,_modo,CASE WHEN _modo='designado' THEN coalesce(_autorizadores,'{}') ELSE '{}' END,btrim(_motivo),auth.uid()) RETURNING id INTO nid; RETURN nid; END $$;
REVOKE ALL ON FUNCTION public.guardar_autoridad_calidad(text,uuid[],text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.guardar_autoridad_calidad(text,uuid[],text) TO authenticated;
CREATE OR REPLACE FUNCTION public.autoridad_calidad_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'La configuración de autoridad conserva su historial'; END IF; IF coalesce(current_setting('tracea.autoridad_rpc',true),'')<>'1' THEN RAISE EXCEPTION 'Usa la configuración de autoridad de calidad'; END IF; RETURN NEW; END $$;
CREATE TRIGGER guard BEFORE INSERT OR UPDATE OR DELETE ON public.org_autoridad_calidad FOR EACH ROW EXECUTE FUNCTION public.autoridad_calidad_guard(); CREATE TRIGGER audit AFTER INSERT ON public.org_autoridad_calidad FOR EACH ROW EXECUTE FUNCTION public.audit_trigger_func();
ALTER TABLE public.org_suplencias DROP CONSTRAINT org_suplencias_facultades_check;
ALTER TABLE public.org_suplencias ADD CONSTRAINT org_suplencias_facultades_check CHECK (cardinality(facultades)>0 AND facultades <@ ARRAY['autorizar','anular','validar_kpi','validar_indicadores']);
COMMENT ON CONSTRAINT org_suplencias_facultades_check ON public.org_suplencias IS 'validar_indicadores is legacy-only; new AC substitutions use autorizar, anular, validar_kpi';
CREATE OR REPLACE FUNCTION public.org_suplencias_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE n text;c text;r text;BEGIN
IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Suplencias no se borran: terminar con motivo';END IF;
IF TG_OP='UPDATE' AND auth.uid() IS NULL AND auth.role()='service_role' AND current_setting('tracea.aviso_sistema',true)='resultado' THEN
IF (to_jsonb(NEW)-ARRAY['aviso_rs_enviado_en','aviso_rs_error','updated_at','updated_by']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['aviso_rs_enviado_en','aviso_rs_error','updated_at','updated_by']) THEN RAISE EXCEPTION 'Sistema solo registra resultado de aviso';END IF;NEW.updated_at:=now();NEW.updated_by:=NULL;RETURN NEW;END IF;
IF NOT public.org_suplencias_acceso(NEW.org_id,true) OR public.is_super_admin() THEN RAISE EXCEPTION 'Sin permiso para suplencias';END IF;
PERFORM pg_advisory_xact_lock(hashtextextended(NEW.org_id::text,712));
IF NEW.rol_sustituido='aseguramiento_calidad' AND public.rol_efectivo(NEW.suplente_user_id,'responsable_sanitario') THEN RAISE EXCEPTION 'El Responsable Sanitario no puede suplir a Aseguramiento de Calidad'; END IF;
IF TG_OP='INSERT' THEN
IF NEW.rol_sustituido NOT IN ('admin','responsable_sanitario','aseguramiento_calidad') OR NEW.categoria NOT IN ('vacaciones','comisión','ausencia','otro') THEN RAISE EXCEPTION 'Rol o categoría inválidos';END IF;
IF NEW.fecha_fin<=NEW.fecha_inicio OR NEW.fecha_fin<=now() OR coalesce(btrim(NEW.motivo),'')='' THEN RAISE EXCEPTION 'Fechas válidas y motivo obligatorio';END IF;
SELECT m.role::text,p.nombre,p.cargo INTO r,n,c FROM public.org_members m JOIN public.profiles p ON p.id=m.user_id AND p.activo WHERE m.org_id=NEW.org_id AND m.user_id=NEW.titular_user_id;
IF r IS DISTINCT FROM NEW.rol_sustituido THEN RAISE EXCEPTION 'Titular no tiene el rol sustituido';END IF;
IF auth.uid()<>NEW.titular_user_id AND NOT (NEW.rol_sustituido='aseguramiento_calidad' AND public.rol_efectivo(auth.uid(),'responsable_sanitario')) AND NOT public.rol_efectivo(auth.uid(),CASE WHEN NEW.rol_sustituido='admin' THEN 'responsable_sanitario'::public.app_role ELSE 'admin'::public.app_role END) THEN RAISE EXCEPTION 'Designa el titular o el otro rol con motivo';END IF;
NEW.titular_nombre:=n;NEW.titular_cargo:=c;
IF NEW.suplente_user_id=NEW.titular_user_id OR EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=NEW.suplente_user_id AND role='super_admin') OR EXISTS(SELECT 1 FROM public.org_members WHERE user_id=NEW.suplente_user_id AND role='super_admin') THEN RAISE EXCEPTION 'Suplente inválido';END IF;
SELECT p.nombre,p.cargo INTO n,c FROM public.org_members m JOIN public.profiles p ON p.id=m.user_id AND p.activo WHERE m.org_id=NEW.org_id AND m.user_id=NEW.suplente_user_id;
IF coalesce(btrim(n),'')='' OR coalesce(btrim(c),'')='' THEN RAISE EXCEPTION 'Suplente requiere membresía activa, nombre y cargo';END IF;
NEW.suplente_nombre:=n;NEW.suplente_cargo:=c;NEW.estado:='pendiente de aceptación';NEW.aceptada_en:=NULL;NEW.respondida_por:=NULL;NEW.terminada_en:=NULL;NEW.motivo_terminacion:=NULL;NEW.registrada_por:=auth.uid();NEW.created_by:=auth.uid();NEW.created_at:=now();NEW.revocada_en:=NULL;NEW.revocada_por:=NULL;
NEW.facultades:=CASE WHEN NEW.rol_sustituido='aseguramiento_calidad' THEN ARRAY['autorizar','anular','validar_kpi'] ELSE ARRAY['autorizar','anular'] END;NEW.aviso_rs_requerido:=true;NEW.aviso_rs_enviado_en:=NULL;NEW.aviso_rs_error:=NULL;
ELSE
IF (to_jsonb(NEW)-ARRAY['estado','aceptada_en','respondida_por','terminada_en','motivo_terminacion','revocada_en','revocada_por','updated_at','updated_by']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['estado','aceptada_en','respondida_por','terminada_en','motivo_terminacion','revocada_en','revocada_por','updated_at','updated_by']) THEN RAISE EXCEPTION 'Designación e identidad inmutables';END IF;
NEW.aceptada_en:=OLD.aceptada_en;NEW.respondida_por:=OLD.respondida_por;NEW.terminada_en:=OLD.terminada_en;NEW.revocada_en:=OLD.revocada_en;NEW.revocada_por:=OLD.revocada_por;
IF OLD.estado='pendiente de aceptación' AND NEW.estado IN ('activa','rechazada') THEN
IF auth.uid()<>OLD.suplente_user_id OR OLD.fecha_fin<=now() OR OLD.revocada_en IS NOT NULL THEN RAISE EXCEPTION 'Solo el suplente responde una designación no vencida';END IF;
NEW.respondida_por:=auth.uid();NEW.aceptada_en:=CASE WHEN NEW.estado='activa' THEN now() ELSE NULL END;
IF NEW.estado='activa' AND EXISTS(SELECT 1 FROM public.org_suplencias s WHERE s.id<>NEW.id AND s.org_id=NEW.org_id AND s.rol_sustituido=NEW.rol_sustituido AND s.estado='activa' AND s.aceptada_en IS NOT NULL AND s.revocada_en IS NULL AND s.fecha_inicio<NEW.fecha_fin AND s.fecha_fin>NEW.fecha_inicio) THEN RAISE EXCEPTION 'Solo una suplencia vigente por rol';END IF;
IF NEW.estado='activa' AND NOT EXISTS(SELECT 1 FROM public.org_members m JOIN public.profiles p ON p.id=m.user_id AND p.activo WHERE m.org_id=NEW.org_id AND m.user_id=coalesce(NEW.titular_user_id,NEW.rs_titular_user_id) AND m.role::text=NEW.rol_sustituido) THEN RAISE EXCEPTION 'Titular ya no tiene el rol';END IF;
ELSIF OLD.estado IN ('pendiente de aceptación','activa') AND NEW.estado='terminada' THEN
IF auth.uid()<>coalesce(OLD.titular_user_id,OLD.rs_titular_user_id) AND auth.uid()<>OLD.suplente_user_id AND NOT (OLD.rol_sustituido='aseguramiento_calidad' AND public.rol_efectivo(auth.uid(),'responsable_sanitario')) AND NOT public.rol_efectivo(auth.uid(),CASE WHEN OLD.rol_sustituido='admin' THEN 'responsable_sanitario'::public.app_role ELSE 'admin'::public.app_role END) THEN RAISE EXCEPTION 'Sin permiso para terminar';END IF;
IF coalesce(btrim(NEW.motivo_terminacion),'')='' THEN RAISE EXCEPTION 'Terminación requiere motivo';END IF;NEW.terminada_en:=now();NEW.revocada_en:=now();NEW.revocada_por:=auth.uid();
ELSE RAISE EXCEPTION 'Transición de suplencia no permitida';END IF;
END IF;
PERFORM set_config('tracea.motivo',CASE WHEN TG_OP='UPDATE' AND NEW.estado='terminada' THEN NEW.motivo_terminacion ELSE NEW.motivo END,true);
NEW.updated_by:=auth.uid();NEW.updated_at:=now();RETURN NEW;END $$;
CREATE OR REPLACE FUNCTION public.kpi_reporte_autoriza(_org uuid,_u uuid) RETURNS text LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE s record; c jsonb; modo text; BEGIN
IF _org IS DISTINCT FROM public.get_user_org_id() OR _u IS NULL OR NOT EXISTS(SELECT 1 FROM public.org_members m JOIN public.profiles p ON p.id=m.user_id AND p.activo WHERE m.org_id=_org AND m.user_id=_u AND m.role<>'super_admin') THEN RETURN NULL; END IF;
c:=public.mi_autoridad_calidad(); modo:=c->>'modo';
IF modo='rs_maxima' THEN IF public.has_role(_u,'responsable_sanitario') THEN RETURN 'Autorizado por el Responsable Sanitario; la empresa no cuenta con Aseguramiento de Calidad'; END IF; RETURN NULL; END IF;
IF modo='designado' THEN IF EXISTS(SELECT 1 FROM jsonb_array_elements_text(c->'autorizadores') x WHERE x.value=_u::text) THEN RETURN ', en ausencia de Aseguramiento de Calidad'; END IF; RETURN NULL; END IF;
IF EXISTS(SELECT 1 FROM public.org_members WHERE org_id=_org AND user_id=_u AND role='aseguramiento_calidad') THEN RETURN ''; END IF;
IF public.has_role(_u,'responsable_sanitario') THEN RETURN NULL; END IF;
SELECT x.* INTO s FROM public.org_suplencias x JOIN public.org_members t ON t.org_id=x.org_id AND t.user_id=x.titular_user_id AND t.role='aseguramiento_calidad' JOIN public.profiles tp ON tp.id=t.user_id AND tp.activo WHERE x.org_id=_org AND x.suplente_user_id=_u AND x.rol_sustituido='aseguramiento_calidad' AND 'autorizar'=ANY(x.facultades) AND x.estado='activa' AND x.aceptada_en IS NOT NULL AND x.revocada_en IS NULL AND x.fecha_inicio<=now() AND now()<x.fecha_fin ORDER BY x.fecha_inicio DESC LIMIT 1;
IF FOUND THEN RETURN '— En suplencia de '||coalesce(s.titular_nombre,'titular de Aseguramiento de Calidad'); END IF; RETURN NULL; END $$;
CREATE OR REPLACE FUNCTION public.congelar_autoridad_kpi() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.emision_preparada IS NOT NULL AND (TG_OP='INSERT' OR OLD.emision_preparada IS NULL) THEN NEW.emision_preparada:=jsonb_set(NEW.emision_preparada,'{reporte,formato_snapshot,autoridad_calidad}',public.mi_autoridad_calidad(),true); END IF; RETURN NEW; END $$;
CREATE TRIGGER zz_autoridad_snapshot BEFORE INSERT OR UPDATE ON public.kpi_reportes FOR EACH ROW EXECUTE FUNCTION public.congelar_autoridad_kpi();